const message = 'The page localStorage was full, click "OK" to clear the localStorage and refresh the page, do you want to continue?\n页面 localStorage 已满，点击"确定"将清空 localStorage 并刷新页面，是否继续?';
function lsGet(key, defaultVal = null) {
    try {
        const value = window.localStorage.getItem(key);
        return value ? JSON.parse(value) : defaultVal;
    } catch (err) {
        return defaultVal;
    }
}
function lsSet(key, val) {
    const StringifiedVal = JSON.stringify(val);
    try {
        return window.localStorage.setItem(key, StringifiedVal);
    } catch (err) {
        if ((null == err ? void 0 : err.name) === 'QuotaExceededError') {
            const result = window.confirm(message);
            if (result) {
                window.localStorage.clear();
                return window.location.reload();
            }
        }
        throw err;
    }
}
const ls = {
    get: lsGet,
    set: lsSet,
    remove (key) {
        return window.localStorage.removeItem(key);
    },
    clear () {
        return window.localStorage.clear();
    }
};
export { ls };
