import { messages } from "./messages.js";
const fallback = (code, ...args)=>{
    let msg = code;
    if (args.length > 0) msg += ` :: ${JSON.stringify(args)}`;
    return msg;
};
const generatorFunction = (code, details = {})=>{
    const message = messages[code];
    if (!message) throw new Error(`Unable to find message for code '${code}'.`);
    return message(details);
};
const messageGenerator = 'production' === process.env.NODE_ENV ? fallback : generatorFunction;
export { messageGenerator };
