import { BaseBytecloudDomainIDService } from "./base-domain-id.service.js";
const url = (()=>{
    try {
        if ("u" > typeof location && 'string' == typeof location.href) return location.href;
        else {
            console.info('[@bytecloud/common-lib]: get location.href failed, use empty string');
            return '';
        }
    } catch (error) {
        console.error('[@bytecloud/common-lib]: ', error);
        return '';
    }
})();
const bytecloudDomainIDService = new BaseBytecloudDomainIDService({
    url: url
});
export { bytecloudDomainIDService };
