import { PackagedJwtService } from "@bytecloud/core-lib";
import { jwtItems } from "./jwt.config.js";
import { initJwtPromiseCache, storageGet, storageSet } from "./jwt-init-util.js";
const cacheObject = initJwtPromiseCache();
const bytecloudJwtService = new PackagedJwtService({
    items: jwtItems,
    storageGet: storageGet,
    storageSet: storageSet,
    promiseCacheObject: cacheObject
});
export { bytecloudJwtService };
