const cnUnits = ['千', '万', '亿', '兆', '京'];
const cnBinaryScale = [1e3, 1e4, 1e8, 1e12, 1e16]; // 对应的数值单位
const enUnits = ['K', 'M', 'B'];
const enBinaryScale = [1e3, 1e6, 1e9]; // 对应的数值单位
export const binaryFormat = (num, type = 'cn', precision = 1, displayMax = 1000, strategy = 'byteCloud') => {
    let units = [];
    let binaryScale = [];
    if (type === 'cn') {
        units = [...cnUnits];
        binaryScale = [...cnBinaryScale];
    }
    else {
        units = [...enUnits];
        binaryScale = [...enBinaryScale];
    }
    if (num < displayMax) {
        return `${num}`; // 小于1000的直接返回数字
    }
    let unitIndex = -1;
    // 确定合适的单位
    for (let i = 0; i < binaryScale.length; i++) {
        if (num >= binaryScale[i]) {
            unitIndex = i;
        }
        else {
            break;
        }
    }
    // 如果没有找到合适的单位，返回原始数字
    if (unitIndex === -1) {
        return `${num}`;
    }
    // 计算以单位为基数的值
    const value = num / binaryScale[unitIndex];
    const formattedNum = value % 1 === 0 ? `${value}` : `${value.toFixed(precision)}`; // 判断是否保留小数
    // 返回格式化后的字符串。此处也可以让用户传formatter，由用户自定义格式化逻辑
    if (strategy === 'byteCloud' && Number.isInteger(Number(formattedNum))) {
        // 字节云策略：整数的地方不需要展示小数点后两位数据
        return `${Number(formattedNum).toFixed(0)}${units[unitIndex]}`;
    }
    return `${formattedNum}${units[unitIndex]}`;
};
