import { bytecloudAsyncJwtManager, bytecloudAsyncJwtService } from "../jwt/index.js";
const convertGatewayJwtKey = (value)=>{
    if ('sinf-boe' === value) return 'sinf';
    if ('volcgroup-boe' === value) return 'volcgroup';
    return value;
};
const getService = (uniqueKey)=>bytecloudAsyncJwtService.getServiceByUniqueKey(convertGatewayJwtKey(uniqueKey)).then((service)=>service);
const gatewayJwtService = {
    logout: (uniqueKey, next)=>{
        getService(uniqueKey).then((service)=>service.logout(next));
    },
    getJwt: (uniqueKey)=>getService(uniqueKey).then((service)=>service.getJwt()),
    setCache: (uniqueKey, jwt)=>{
        bytecloudAsyncJwtService.setCache(convertGatewayJwtKey(uniqueKey), jwt);
    },
    getService: (uniqueKey)=>getService(uniqueKey),
    getJwtByJwtManager: (uniqueKey)=>bytecloudAsyncJwtManager.getJwt({
            uniqueKeyOrDomainID: convertGatewayJwtKey(uniqueKey)
        })
};
const checkType = (value)=>value;
const gateway_jwt_service_value = 'online';
checkType(gateway_jwt_service_value);
export { gatewayJwtService };
