function enableDevLogs() {
    self.__BC_DISABLE_DEV_LOGS = false;
}
const logger = 'production' === process.env.NODE_ENV ? null : (()=>{
    if (!('__BC_DISABLE_DEV_LOGS' in globalThis)) self.__BC_DISABLE_DEV_LOGS = true;
    let inGroup = false;
    const methodToColorMap = {
        debug: '#7f8c8d',
        log: '#2ecc71',
        warn: '#f39c12',
        error: '#c0392b',
        groupCollapsed: '#3498db',
        groupEnd: null
    };
    const print = function(method, args) {
        if (self.__BC_DISABLE_DEV_LOGS) return;
        if ('groupCollapsed' === method) {
            if (/^((?!chrome|android).)*safari/i.test(navigator.userAgent)) return void console[method](...args);
        }
        const styles = [
            `background: ${methodToColorMap[method]}`,
            'border-radius: 0.5em',
            'color: white',
            'font-weight: bold',
            'padding: 2px 0.5em'
        ];
        const logPrefix = inGroup ? [] : [
            '%c@bytecloud/strategies',
            styles.join(';')
        ];
        console[method](...logPrefix, ...args);
        if ('groupCollapsed' === method) inGroup = true;
        if ('groupEnd' === method) inGroup = false;
    };
    const api = {};
    const loggerMethods = Object.keys(methodToColorMap);
    for (const key of loggerMethods){
        const method = key;
        api[method] = (...args)=>{
            print(method, args);
        };
    }
    return api;
})();
export { enableDevLogs, logger };
